import{_ as a,o as s,c as t,a3 as i}from"./chunks/framework.B9qR_F1m.js";const k=JSON.parse('{"title":"Recipes prepared by an AI assistant: ripeat drafts","description":"","frontmatter":{},"headers":[],"relativePath":"drafts.md","filePath":"drafts.md"}'),r={name:"drafts.md"};function n(o,e,d,l,h,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="recipes-prepared-by-an-ai-assistant-ripeat-drafts" tabindex="-1">Recipes prepared by an AI assistant: <code>ripeat drafts</code> <a class="header-anchor" href="#recipes-prepared-by-an-ai-assistant-ripeat-drafts" aria-label="Permalink to &quot;Recipes prepared by an AI assistant: \`ripeat drafts\`&quot;">​</a></h1><p>An AI assistant connected through <code>ripeat mcp</code> (<a href="./mcp">ripeat as an MCP server</a>) can <strong>prepare</strong> a recipe for a tool that has none. It cannot <strong>create</strong> one. The recipe is yours only after you read it and approve it in a terminal.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>The assistant calls <code>ripeat_draft_recipe</code> with a tool&#39;s name (and optionally a source such as <code>apt</code>, <code>brew</code> or <code>github</code>). For a vendor installer it can call <code>ripeat_draft_vendor</code> with the vendor&#39;s HTTPS address and published SHA-256. Your app must show a confirmation before ripeat downloads or inspects it.</li><li><strong>ripeat writes the recipe, not the assistant.</strong> For package-manager and GitHub requests it looks the tool up and drafts it with the same fixed rules as <code>ripeat add</code> (<a href="./find-and-add">Install by name</a>). For a vendor request it inspects the confirmed download and checks its checksum and signature. It checks the recipe and saves it in <code>$RIPEAT_HOME/drafts/&lt;name&gt;.yaml</code>. The tool accepts a name, a source and a recipe name, and no recipe text, so the assistant has no way to put its own commands into a recipe. The result says where the file is (<code>saved_to</code>), and <code>ripeat_list_drafts</code> says which folder it looked in.</li><li><strong>A draft does nothing.</strong> ripeat never reads the drafts folder as recipes: <code>ripeat plan</code> and <code>ripeat install</code> still say there is no recipe for the name.</li><li>You review and approve it yourself:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drafts</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                     # the drafts waiting, with install method and risk</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drafts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lazygit</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # the recipe, its risk and the reasons</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drafts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> approve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lazygit</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # asks &quot;Approve ... ? [y/N]&quot;; on yes it becomes a recipe</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ripeat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drafts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reject</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lazygit</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # delete the draft</span></span></code></pre></div><p><code>approve</code> checks the draft again from the file as it is now (it may have been edited), shows the recipe and its risk, and asks. <strong>There is no <code>--yes</code></strong>, and without a terminal it refuses, so only a person can answer. On a yes the file moves into <code>$RIPEAT_HOME/recipes/</code>, marked as approved, and <code>ripeat install &lt;name&gt;</code> works.</p><h2 id="what-a-draft-can-be" tabindex="-1">What a draft can be <a class="header-anchor" href="#what-a-draft-can-be" aria-label="Permalink to &quot;What a draft can be&quot;">​</a></h2><ul><li><strong>Package-manager, GitHub-release and signed vendor-installer sources.</strong> The vendor tool supports <code>.dmg</code> and <code>.pkg</code> on macOS, <code>.msi</code> and <code>.exe</code> on Windows. It requires the vendor&#39;s published checksum and verifies and pins the signer; unsigned installers are refused. An <code>.exe</code> also needs the product name and vendor-documented silent arguments. It never runs the installer. <code>shell</code> and <code>manual</code> drafts are refused at approval.</li><li><strong>Not over an existing recipe.</strong> A name that already has a recipe is not drafted, and approval refuses to replace one.</li><li><strong>Within the administrator policy.</strong> A source the policy forbids is not drafted (<a href="./admin-policy">Administrator policy</a>), and approval checks again.</li><li><strong>A GitHub source downloads</strong> the release file to a temporary folder to find the program inside it. Its SHA-256 is checked, nothing in it is run, and the folder is deleted afterwards.</li></ul><h2 id="what-the-assistant-also-gets" tabindex="-1">What the assistant also gets <a class="header-anchor" href="#what-the-assistant-also-gets" aria-label="Permalink to &quot;What the assistant also gets&quot;">​</a></h2><p><code>ripeat_list_drafts</code> and <code>ripeat_get_draft</code> read the waiting drafts (text, method, risk, any problem). It is told to hand you the <code>ripeat drafts approve &lt;name&gt;</code> command and never to run it.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>The risk shown is the one <code>ripeat assess</code> would give the recipe once it is yours (a recipe in your folder counts as one you added).</li><li>A draft that does not fit the current machine (no option for this OS) cannot be approved here.</li><li>Approving does not install anything. Installing is the usual <code>ripeat install</code>, with its own plan, risk rating and question.</li></ul>`,12)])])}const f=a(r,[["render",n]]);export{k as __pageData,f as default};
